#!/usr/bin/env python3
"""Compare two S0 semantic snapshot JSON files generated by S0SemanticProbe."""

import argparse
import json
import pathlib
from collections import defaultdict


def classify_prefix(key: str) -> str:
    if key.startswith("globalVars."):
        return "globalVars"
    if key.startswith("static/"):
        return "static"
    if key.startswith("ddol/Knight:") and "HeroController" in key:
        return "Knight.HeroController"
    if key.startswith("ddol/Knight:") and "PlayMakerFSM" in key:
        return "Knight.FSM"
    if key.startswith("ddol/Knight/"):
        return "Knight.Children"
    if key.startswith("ddol/_GameManager"):
        return "GameManager"
    if key.startswith("ddol/_GameCameras"):
        return "GameCameras"
    if key.startswith("ddol/_AudioManager") or "Audio" in key:
        return "AudioManager"
    if key.startswith("ddol/_UIManager"):
        return "UIManager"
    if key.startswith("ddol/Pool") or "ObjectPool" in key:
        return "ObjectPool"
    return "OtherDDOL"


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--left", required=True)
    parser.add_argument("--right", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()

    left = json.loads(pathlib.Path(args.left).read_text(encoding="utf-8"))
    right = json.loads(pathlib.Path(args.right).read_text(encoding="utf-8"))

    lflat = left.get("flat", {})
    rflat = right.get("flat", {})
    all_keys = sorted(set(lflat.keys()) | set(rflat.keys()))

    diffs = []
    by_domain = defaultdict(list)
    for k in all_keys:
        in_l = k in lflat
        in_r = k in rflat
        lv = lflat.get(k)
        rv = rflat.get(k)
        if not in_l or not in_r or lv != rv:
            rec = {
                "path": k,
                "domain": classify_prefix(k),
                "left": lv if in_l else "<MISSING>",
                "right": rv if in_r else "<MISSING>",
            }
            diffs.append(rec)
            by_domain[rec["domain"]].append(rec)

    summary = {
        "leftMeta": left.get("meta"),
        "rightMeta": right.get("meta"),
        "totalFlatKeysLeft": len(lflat),
        "totalFlatKeysRight": len(rflat),
        "totalDiffCount": len(diffs),
        "diffCountByDomain": {d: len(v) for d, v in sorted(by_domain.items())},
        "diffs": diffs,
    }
    out_path = pathlib.Path(args.output)
    out_path.write_text(json.dumps(summary, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Compared {args.left} vs {args.right}: {len(diffs)} diffs written to {args.output}")
    for d, items in sorted(by_domain.items()):
        print(f"  {d}: {len(items)}")


if __name__ == "__main__":
    main()
